{
  "id": "arrays/strict-in-array-narrowing",
  "title": "Strict in_array() over a literal haystack narrows the needle to the string elements",
  "domain": "arrays",
  "rule_class": "argument.type",
  "php": { "min": "8.1" },
  "targets": ["src"],
  "ground_truth": {
    "basis": "runtime_proof",
    "statement": "in_array($x, $y, true) compares with ===. In this fixture the haystack elements are 'a', 'b' or an int, so a true result means the needle is identical to one of them, and neither a bool nor a numeric string can be: for string|bool $x inside the guard, $x is 'a' or 'b'. Passing it to a parameter typed \"a\"|\"b\" is therefore sound, and no diagnostic belongs on that call.",
    "runtime_script": "runtime/check.php",
    "citation": "https://www.php.net/manual/en/function.in-array.php"
  },
  "expect": {
    "phpstan": { "mode": "clean" },
    "psalm": { "mode": "clean" },
    "mago": {
      "mode": "clean",
      "forbidden": [
        { "code": "possibly-invalid-argument", "line": 17 }
      ]
    }
  },
  "notes": "Mago 1.57.0 reports possibly-invalid-argument on the guarded call and describes the argument as numeric-string|'a'|'b', i.e. it reconciles the needle against a numeric-string alternative of the haystack even though the comparison is strict. PHPStan 2.3.1 and Psalm 6.20.0 narrow to 'a'|'b' and stay silent. The runtime script carries the asymmetric control the claim needs: the same needle/haystack pair under the default loose comparison matches ('1' is in [1]) while the strict form does not, so the third argument - not the values alone - is what makes the narrowing hold. The pattern was taken from /home/abez/projects/mago-upstream-prep/repro/strict-in-array-int-haystack-string-coercion/repro.php; the fixture is a clean-room rewrite.",
  "provenance": {
    "sources": [
      {
        "kind": "historical_reproducer",
        "path": "/home/abez/projects/mago-upstream-prep/repro/strict-in-array-int-haystack-string-coercion/repro.php",
        "note": "pattern source only; the claim was re-derived from the strict comparison semantics"
      }
    ],
    "tool_pins": { "mago": "1.57.0", "phpstan": "2.3.1", "psalm": "6.20.0" },
    "source_checkouts": {
      "phpstan": "2c12dac5e4f8626c8a7cfc0b4bb9c5ce48d37c96",
      "psalm": "62e52cd9fe3ab4429debc0eb0306057419b0a9d6"
    }
  }
}

