{
  "id": "narrowing/negated-instanceof-unrelated-class",
  "title": "instanceof against an unrelated class is always false, so its negation is always true",
  "domain": "narrowing",
  "rule_class": "impossible-condition",
  "php": { "min": "8.0" },
  "targets": ["src"],
  "ground_truth": {
    "basis": "runtime_proof",
    "statement": "PHP gives every object exactly one parent chain, and Beta is neither a parent nor an interface of Alpha, so no instance of Alpha (or of a subclass of Alpha) is an instance of Beta. `!($value instanceof Beta)` is true for every value the parameter can hold.",
    "runtime_script": "runtime/check.php",
    "citation": "https://www.php.net/manual/en/language.operators.type.php"
  },
  "expect": {
    "phpstan": {
      "mode": "diagnostics",
      "required": [
        { "code": "instanceof.alwaysFalse", "line": 18 }
      ]
    },
    "psalm": {
      "mode": "diagnostics",
      "required": [
        { "code": "RedundantCondition", "line": 18 }
      ]
    },
    "mago": {
      "mode": "unsupported",
      "reason": "Mago 1.57.0 analyzes a bare return as an expression. Unary Not negates the inferred instanceof result but does not invoke conditional diagnostics or assertion reconciliation. Its silence here is outside this warning's reporting scope; impossible instanceof conditions remain supported and must be tested separately.",
